    place-items: center;
    padding: 22px;
    z-index: 4;
    background: radial-gradient(circle, rgba(255,255,255,.06), rgba(0,0,0,.72));
  }
  .card {
    width: min(560px, 100%);
    background: rgba(10,10,10,.88);
    border: 1px solid rgba(255,255,255,.18);
    border-radius: 24px;
    padding: 24px;
    box-shadow: 0 24px 80px rgba(0,0,0,.55);
  }
  h1 {
    margin: 0 0 8px;
    font-size: clamp(30px, 8vw, 54px);
    letter-spacing: -1px;
  }
  p {
    margin: 8px 0;
    color: rgba(255,255,255,.82);
    line-height: 1.45;
  }
  button {
    border: 0;
    border-radius: 16px;
    padding: 14px 18px;
    margin-top: 14px;
    font-weight: 900;
    font-size: 16px;
    background: #ffd84d;
    color: #1b1600;
    cursor: pointer;
    width: 100%;
  }
  .touch {
    position: fixed;
