</head>
<body>
<canvas id="game"></canvas>

<div class="hud">
  <div class="panel">
    <div class="small">TIME</div>
    <div class="big" id="time">0.00</div>
  </div>
  <div class="panel">
    <div class="small">CHECKPOINT</div>
    <div class="big" id="cp">1 / 6</div>
  </div>
  <div class="panel">
    <div class="small">BEST</div>
    <div class="big" id="best">--</div>
  </div>
</div>

<div class="center" id="overlay">
  <div class="card">
    <h1>Tiny Rally</h1>
    <p>Hit every glowing checkpoint in order. Beat your ghost best by cutting cleaner lines.</p>
    <p><b>Keyboard</b> arrow keys or WASD. Space brakes. R restarts.</p>
    <p><b>Phone</b> use the touch steering and pedals.</p>
    <button id="startBtn">Start run</button>
  </div>
</div>

<div class="touch">
  <div class="pad">
    <button data-key="left">◀</button>
    <button data-key="right">▶</button>
  </div>
  <div class="pedals">
    <button class="gas" data-key="up">▲</button>
    <button class="brake" data-key="down">▼</button>
  </div>
</div>

<script>
(() => {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const timeEl = document.getElementById("time");
  const cpEl = document.getElementById("cp");
  const bestEl = document.getElementById("best");
  const overlay = document.getElementById("overlay");
  const startBtn = document.getElementById("startBtn");

  let W = 0, H = 0, scale = 1;
  function resize() {
    W = canvas.width = Math.floor(innerWidth * devicePixelRatio);
    H = canvas.height = Math.floor(innerHeight * devicePixelRatio);
    canvas.style.width = innerWidth + "px";
    canvas.style.height = innerHeight + "px";
    scale = Math.min(W / 900, H / 620);
  }
  addEventListener("resize", resize);
  resize();

  const bestKey = "tinyRallyBest";
  let best = Number(localStorage.getItem(bestKey) || 0);
  bestEl.textContent = best ? best.toFixed(2) : "--";

  const keys = { up:false, down:false, left:false, right:false };
  const car = { x: 170, y: 470, a: -0.35, v: 0, trail: [] };
  const start = { x: 170, y: 470, a: -0.35 };

  const checkpoints = [
    { x: 320, y: 370, r: 34 },
    { x: 510, y: 245, r: 34 },
    { x: 720, y: 300, r: 34 },
    { x: 680, y: 475, r: 34 },
    { x: 420, y: 500, r: 34 },
    { x: 210, y: 250, r: 34 }
  ];

  let running = false;
  let done = false;
  let cp = 0;
  let t0 = 0;
  let elapsed = 0;
  let message = "";
  let msgTimer = 0;

  function reset(startNow = true) {
    car.x = start.x;
    car.y = start.y;
    car.a = start.a;
    car.v = 0;
    car.trail = [];
    cp = 0;
    elapsed = 0;
    done = false;
    message = "";
    msgTimer = 0;
    running = startNow;
    t0 = performance.now();
    overlay.style.display = startNow ? "none" : "grid";
    updateHud();
  }

  startBtn.onclick = () => reset(true);

  addEventListener("keydown", e => {
    if (["ArrowUp","w","W"].includes(e.key)) keys.up = true;
    if (["ArrowDown","s","S"," "].includes(e.key)) keys.down = true;
    if (["ArrowLeft","a","A"].includes(e.key)) keys.left = true;
    if (["ArrowRight","d","D"].includes(e.key)) keys.right = true;
    if (["r","R"].includes(e.key)) reset(true);
    if (!running && e.key === "Enter") reset(true);
  });
  addEventListener("keyup", e => {
    if (["ArrowUp","w","W"].includes(e.key)) keys.up = false;
    if (["ArrowDown","s","S"," "].includes(e.key)) keys.down = false;
    if (["ArrowLeft","a","A"].includes(e.key)) keys.left = false;
    if (["ArrowRight","d","D"].includes(e.key)) keys.right = false;
  });

  document.querySelectorAll(".touch button").forEach(btn => {
    const k = btn.dataset.key;
    const on = e => { e.preventDefault(); keys[k] = true; };
    const off = e => { e.preventDefault(); keys[k] = false; };
    btn.addEventListener("pointerdown", on);
    btn.addEventListener("pointerup", off);
    btn.addEventListener("pointercancel", off);
    btn.addEventListener("pointerleave", off);
  });

  function fmt(n) {
    return n.toFixed(2);
  }

  function updateHud() {
    timeEl.textContent = fmt(elapsed);
    cpEl.textContent = (Math.min(cp + 1, checkpoints.length)) + " / " + checkpoints.length;
    bestEl.textContent = best ? fmt(best) : "--";
  }

  function worldToScreen(x, y) {
    const ox = W / 2 - car.x * scale;
    const oy = H / 2 - car.y * scale;
    return { x: ox + x * scale, y: oy + y * scale };
  }

  function drawTrack() {
    ctx.save();
    ctx.scale(scale, scale);
    const ox = W / 2 / scale - car.x;
    const oy = H / 2 / scale - car.y;
    ctx.translate(ox, oy);

    ctx.fillStyle = "#214225";
    ctx.fillRect(-400, -300, 1700, 1200);

    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    ctx.strokeStyle = "#3a3028";
    ctx.lineWidth = 150;
    ctx.beginPath();
    ctx.moveTo(150, 475);
    ctx.bezierCurveTo(170, 260, 360, 190, 515, 220);
    ctx.bezierCurveTo(760, 260, 820, 410, 690, 505);
    ctx.bezierCurveTo(570, 595, 260, 575, 190, 445);
    ctx.bezierCurveTo(125, 325, 220, 220, 360, 260);
    ctx.stroke();

    ctx.strokeStyle = "#6d6258";
    ctx.lineWidth = 118;
    ctx.stroke();

    ctx.strokeStyle = "rgba(255,255,255,.18)";
    ctx.lineWidth = 4;
    ctx.setLineDash([18, 18]);
    ctx.beginPath();
    ctx.moveTo(150, 475);
    ctx.bezierCurveTo(170, 260, 360, 190, 515, 220);
    ctx.bezierCurveTo(760, 260, 820, 410, 690, 505);
    ctx.bezierCurveTo(570, 595, 260, 575, 190, 445);
    ctx.bezierCurveTo(125, 325, 220, 220, 360, 260);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = "rgba(0,0,0,.22)";
    for (let i = 0; i < 60; i++) {
      const x = (i * 137) % 1100 - 130;
      const y = (i * 89) % 800 - 120;
      ctx.beginPath();
      ctx.arc(x, y, 2 + (i % 5), 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = "#fff";
    ctx.fillRect(128, 436, 14, 78);
    ctx.fillStyle = "#111";
    for (let y = 436; y < 514; y += 18) {
      ctx.fillRect(128, y, 14, 9);
    }

    ctx.restore();
  }

  function drawCheckpoints() {
    checkpoints.forEach((c, i) => {
      const p = worldToScreen(c.x, c.y);
      const active = i === cp;
      const cleared = i < cp;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.scale(scale, scale);

      ctx.globalAlpha = cleared ? .22 : 1;
      ctx.strokeStyle = active ? "#ffd84d" : "#ffffff";
      ctx.fillStyle = active ? "rgba(255,216,77,.18)" : "rgba(255,255,255,.08)";
      ctx.lineWidth = active ? 7 : 4;
      ctx.beginPath();
      ctx.arc(0, 0, c.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      if (active) {
        ctx.strokeStyle = "rgba(255,216,77,.38)";
        ctx.lineWidth = 16;
        ctx.beginPath();
        ctx.arc(0, 0, c.r + 12 + Math.sin(performance.now() / 120) * 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      ctx.fillStyle = active ? "#ffd84d" : "#fff";
      ctx.font = "900 26px system-ui";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(i + 1, 0, 1);
      ctx.restore();
    });
  }

  function drawCar() {
    const p = worldToScreen(car.x, car.y);

    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,.16)";
    ctx.lineWidth = 3 * scale;
    ctx.beginPath();
    for (let i = 0; i < car.trail.length; i++) {
      const q = worldToScreen(car.trail[i].x, car.trail[i].y);
      if (i === 0) ctx.moveTo(q.x, q.y);
      else ctx.lineTo(q.x, q.y);
    }
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(car.a);
    ctx.scale(scale, scale);

    ctx.fillStyle = "rgba(0,0,0,.35)";
    ctx.fillRect(-16, -10, 34, 22);

    ctx.fillStyle = "#e74b3c";
    ctx.beginPath();
    ctx.roundRect(-17, -11, 34, 22, 6);
    ctx.fill();

    ctx.fillStyle = "#ffd84d";
    ctx.beginPath();
    ctx.moveTo(18, 0);
    ctx.lineTo(4, -8);
    ctx.lineTo(4, 8);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "rgba(255,255,255,.72)";
    ctx.fillRect(-5, -7, 9, 14);
    ctx.restore();
  }

  function drawMessage() {
    if (!message || msgTimer <= 0) return;
    ctx.save();
    ctx.globalAlpha = Math.min(1, msgTimer / 30);
    ctx.fillStyle = "rgba(0,0,0,.55)";
    ctx.roundRect(W / 2 - 190, H * .22 - 34, 380, 68, 18);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.font = `900 ${Math.max(22, 30 * scale)}px system-ui`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(message, W / 2, H * .22);
    ctx.restore();
  }

  CanvasRenderingContext2D.prototype.roundRect ||= function(x, y, w, h, r) {
    this.beginPath();
    this.moveTo(x + r, y);
    this.arcTo(x + w, y, x + w, y + h, r);
    this.arcTo(x + w, y + h, x, y + h, r);
    this.arcTo(x, y + h, x, y, r);
    this.arcTo(x, y, x + w, y, r);
    this.closePath();
    return this;
  };

  function physics(dt) {
    if (!running || done) return;

    const accel = keys.up ? 250 : 0;
    const brake = keys.down ? 340 : 0;
    car.v += accel * dt;
    car.v -= brake * dt * Math.sign(car.v || 1);
    car.v *= Math.pow(.985, dt * 60);
    car.v = Math.max(-120, Math.min(360, car.v));

    const steer = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
    const grip = Math.min(1, Math.abs(car.v) / 180);
    car.a += steer * grip * 3.2 * dt * (car.v >= 0 ? 1 : -1);

    car.x += Math.cos(car.a) * car.v * dt;
    car.y += Math.sin(car.a) * car.v * dt;

    car.trail.push({ x: car.x, y: car.y });
    if (car.trail.length > 80) car.trail.shift();

    elapsed = (performance.now() - t0) / 1000;

    const c = checkpoints[cp];
    const d = Math.hypot(car.x - c.x, car.y - c.y);
    if (d < c.r) {
      cp++;
      if (cp >= checkpoints.length) {
        running = false;
        done = true;
        const oldBest = best;
        if (!best || elapsed < best) {
          best = elapsed;
          localStorage.setItem(bestKey, String(best));
          message = oldBest ? "NEW BEST -" + fmt(oldBest - best) + "s" : "FIRST TIME SET";
        } else {
          message = "+" + fmt(elapsed - best) + "s off best";
        }
        msgTimer = 180;
        setTimeout(() => {
          overlay.style.display = "grid";
          overlay.querySelector("h1").textContent = "Run finished";
          overlay.querySelector("p").innerHTML = `Time <b>${fmt(elapsed)}</b><br>Best <b>${fmt(best)}</b><br>Press start or R to retry.`;
          startBtn.textContent = "Retry";
        }, 900);
      } else {
        message = "Checkpoint " + cp;
        msgTimer = 55;
      }
    }

    msgTimer--;
    updateHud();
  }

  let last = performance.now();
  function loop(now) {
    const dt = Math.min(.033, (now - last) / 1000);
    last = now;

    physics(dt);

    ctx.clearRect(0, 0, W, H);
    drawTrack();
    drawCheckpoints();
    drawCar();
    drawMessage();

    requestAnimationFrame(loop);
  }

  reset(false);
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>

