    { x: 660, y: 225, r: 35, target: 15.0 },
    { x: 815, y: 380, r: 35, target: 20.6 },
    { x: 745, y: 545, r: 35, target: 25.5 }
  ];

  const lapTarget = 27.6;

  const scenery = Array.from({ length: 110 }, (_, i) => ({
    x: (i * 137) % 1160 - 120,
    y: (i * 91) % 820 - 70,
    r: 3 + (i % 8),
    kind: i % 5
  }));

  let running = false;
  let done = false;
  let lap = 1;
  let cp = 0;
  let t0 = 0;
  let elapsed = 0;
  let lapStartTime = 0;
  let lastCpTime = 0;
  let splitText = "--";
  let message = "";
  let subMessage = "";
  let msgTimer = 0;
  let offRoad = false;

  function fmt(n) {
    return n.toFixed(2);
  }

  function medalFor(t) {
    if (t <= medals[0].t) return medals[0];
    if (t <= medals[1].t) return medals[1];
    if (t <= medals[2].t) return medals[2];
    return { name: "No medal", icon: "⏱️", t: Infinity };
  }

  function nextMedalText(t) {
    if (t <= medals[0].t) return "Gold pace. Start hunting tenths.";
    if (t <= medals[1].t) return "Next target: Gold at 44.00s.";
    if (t <= medals[2].t) return "Next target: Silver at 50.00s.";
    return "Next target: Bronze at 58.00s.";
  }

  function updateHud() {
    timeEl.textContent = fmt(elapsed);
    lapEl.textContent = Math.min(lap, totalLaps) + " / " + totalLaps;
    cpEl.textContent = cp >= checkpoints.length ? "GATE" : (cp + 1) + " / " + checkpoints.length;
    splitEl.textContent = splitText;
    bestEl.textContent = best ? fmt(best) : "--";
  }

  function reset(startNow = true) {
    car.x = start.x;
    car.y = start.y;
    car.a = start.a;
    car.v = 0;
    car.trail = [];
    car.wasNearGate = true;
    lap = 1;
    cp = 0;
    elapsed = 0;
    lapStartTime = 0;
    lastCpTime = 0;
    splitText = "--";
    done = false;
    offRoad = false;
    message = "";
    subMessage = "";
    msgTimer = 0;
    running = startNow;
    t0 = performance.now();
    overlay.style.display = startNow ? "none" : "grid";
    updateHud();
  }

  startBtn.onclick = () => reset(true);

  addEventListener("keydown", e => {
    if (["ArrowUp","w","W"].includes(e.key)) keys.up = true;
    if (["ArrowDown","s","S"," "].includes(e.key)) keys.down = true;
    if (["ArrowLeft","a","A"].includes(e.key)) keys.left = true;
    if (["ArrowRight","d","D"].includes(e.key)) keys.right = true;
    if (["r","R"].includes(e.key)) reset(true);
    if (!running && e.key === "Enter") reset(true);
  });

  addEventListener("keyup", e => {
    if (["ArrowUp","w","W"].includes(e.key)) keys.up = false;
    if (["ArrowDown","s","S"," "].includes(e.key)) keys.down = false;
    if (["ArrowLeft","a","A"].includes(e.key)) keys.left = false;
    if (["ArrowRight","d","D"].includes(e.key)) keys.right = false;
  });

  document.querySelectorAll(".touch button").forEach(btn => {
    const k = btn.dataset.key;
    const on = e => { e.preventDefault(); keys[k] = true; };
    const off = e => { e.preventDefault(); keys[k] = false; };
    btn.addEventListener("pointerdown", on);
    btn.addEventListener("pointerup", off);
    btn.addEventListener("pointercancel", off);
    btn.addEventListener("pointerleave", off);
  });

  function worldToScreen(x, y) {
    const ox = W / 2 - car.x * scale;
    const oy = H / 2 - car.y * scale;
    return { x: ox + x * scale, y: oy + y * scale };
  }

  function withWorld(fn) {
    ctx.save();
    ctx.scale(scale, scale);
    ctx.translate(W / 2 / scale - car.x, H / 2 / scale - car.y);
    fn();
    ctx.restore();
  }

  function drawRibbon(points, width, color, dash = null) {
    ctx.save();
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    if (dash) ctx.setLineDash(dash);
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length - 1; i++) {
      const mx = (points[i].x + points[i + 1].x) / 2;
      const my = (points[i].y + points[i + 1].y) / 2;
      ctx.quadraticCurveTo(points[i].x, points[i].y, mx, my);
    }
    ctx.lineTo(points[points.length - 1].x, points[points.length - 1].y);
    ctx.stroke();
    ctx.restore();
  }

  function distToSegment(px, py, ax, ay, bx, by) {
    const vx = bx - ax;
    const vy = by - ay;
    const wx = px - ax;
    const wy = py - ay;
    const len2 = vx * vx + vy * vy;
    let t = len2 ? (wx * vx + wy * vy) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    const x = ax + vx * t;
    const y = ay + vy * t;
    return Math.hypot(px - x, py - y);
  }

  function pointOnTrack(x, y) {
    let bestD = Infinity;
    for (let i = 0; i < route.length - 1; i++) {
      const a = route[i];
      const b = route[i + 1];
      bestD = Math.min(bestD, distToSegment(x, y, a.x, a.y, b.x, b.y));
    }
    return bestD < 74;
  }

  function drawTrack() {
    withWorld(() => {
      ctx.fillStyle = "#244323";
      ctx.fillRect(-450, -350, 1900, 1300);

      scenery.forEach(s => {
        if (s.kind === 0) {
          ctx.fillStyle = "rgba(8,25,10,.55)";
          ctx.beginPath();
          ctx.arc(s.x, s.y, s.r + 7, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = "rgba(28,78,31,.85)";
          ctx.beginPath();
          ctx.arc(s.x, s.y, s.r + 3, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillStyle = "rgba(0,0,0,.16)";
          ctx.beginPath();
          ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
          ctx.fill();
        }
      });

      drawRibbon(route, 190, "#28231f");
      drawRibbon(route, 150, "#655c52");
      drawRibbon(route, 122, "#756c60");
      drawRibbon(route, 5, "rgba(255,255,255,.18)", [18, 20]);
      drawRibbon(route, 3, "rgba(255,216,77,.34)", [38, 28]);

      ctx.lineCap = "butt";
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.moveTo(startGate.a.x, startGate.a.y);
      ctx.lineTo(startGate.b.x, startGate.b.y);
      ctx.stroke();

      const dx = startGate.b.x - startGate.a.x;
      const dy = startGate.b.y - startGate.a.y;
      const len = Math.hypot(dx, dy);
      const ux = dx / len;
      const uy = dy / len;

      for (let i = 0; i < 8; i++) {
        const x = startGate.a.x + ux * i * 12;
        const y = startGate.a.y + uy * i * 12;
        ctx.fillStyle = i % 2 ? "#111" : "#fff";
        ctx.beginPath();
        ctx.arc(x, y, 7, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = "#ffd84d";
      ctx.font = "900 20px system-ui";
      ctx.textAlign = "center";
      ctx.fillText("START / FINISH", startGate.center.x - 18, startGate.center.y - 52);

      checkpoints.forEach((p, i) => {
        ctx.fillStyle = "rgba(255,255,255,.18)";
        ctx.font = "900 18px system-ui";
        ctx.textAlign = "center";
        ctx.fillText(i + 1, p.x, p.y - 52);
      });

      if (offRoad) {
        ctx.fillStyle = "rgba(255,216,77,.12)";
        ctx.font = "900 22px system-ui";
        ctx.textAlign = "center";
        ctx.fillText("OFF ROAD", car.x, car.y - 58);
      }
    });
  }

  function drawCheckpoints() {
    checkpoints.forEach((c, i) => {
      const p = worldToScreen(c.x, c.y);
      const active = i === cp;
      const cleared = i < cp;

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.scale(scale, scale);
      ctx.globalAlpha = cleared ? .18 : 1;

      ctx.fillStyle = active ? "rgba(255,216,77,.20)" : "rgba(255,255,255,.08)";
      ctx.strokeStyle = active ? "#ffd84d" : "rgba(255,255,255,.72)";
      ctx.lineWidth = active ? 7 : 4;

      ctx.beginPath();
      ctx.arc(0, 0, c.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      if (active) {
        ctx.strokeStyle = "rgba(255,216,77,.36)";
        ctx.lineWidth = 17;
        ctx.beginPath();
        ctx.arc(0, 0, c.r + 13 + Math.sin(performance.now() / 120) * 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      ctx.fillStyle = active ? "#ffd84d" : "#fff";
      ctx.font = "900 26px system-ui";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(i + 1, 0, 1);
      ctx.restore();
    });
  }

  function drawNextArrow() {
    if (done) return;

    const target = cp >= checkpoints.length ? startGate.center : checkpoints[cp];
    const dx = target.x - car.x;
    const dy = target.y - car.y;
    const ang = Math.atan2(dy, dx);
    const dist = Math.hypot(dx, dy);

    ctx.save();
    ctx.translate(W / 2, H / 2);
    ctx.rotate(ang);
    ctx.translate(0, -68 * scale);

    ctx.fillStyle = "rgba(0,0,0,.38)";
    ctx.beginPath();
    ctx.roundRect(24 * scale, -22 * scale, 124 * scale, 44 * scale, 16 * scale);
    ctx.fill();

    ctx.fillStyle = cp >= checkpoints.length ? "#7cff8a" : "#ffd84d";
    ctx.beginPath();
    ctx.moveTo(70 * scale, 0);
    ctx.lineTo(25 * scale, -22 * scale);
    ctx.lineTo(34 * scale, -7 * scale);
    ctx.lineTo(-12 * scale, -7 * scale);
    ctx.lineTo(-12 * scale, 7 * scale);
    ctx.lineTo(34 * scale, 7 * scale);
    ctx.lineTo(25 * scale, 22 * scale);
    ctx.closePath();
    ctx.fill();

    ctx.rotate(-ang);
    ctx.fillStyle = "#fff";
    ctx.font = `900 ${Math.max(13, 15 * scale)}px system-ui`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(cp >= checkpoints.length ? "GATE" : Math.round(dist) + "m", 86 * scale, 0);
    ctx.restore();
  }

  function drawCar() {
    const p = worldToScreen(car.x, car.y);

    ctx.save();
    ctx.strokeStyle = offRoad ? "rgba(255,216,77,.30)" : "rgba(255,255,255,.18)";
    ctx.lineWidth = 3 * scale;
    ctx.beginPath();
    for (let i = 0; i < car.trail.length; i++) {
      const q = worldToScreen(car.trail[i].x, car.trail[i].y);
      if (i === 0) ctx.moveTo(q.x, q.y);
      else ctx.lineTo(q.x, q.y);
    }
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(car.a);
    ctx.scale(scale, scale);

    ctx.fillStyle = "rgba(0,0,0,.38)";
    ctx.fillRect(-17, -11, 36, 24);

    ctx.fillStyle = "#e74b3c";
    ctx.beginPath();
    ctx.roundRect(-17, -11, 34, 22, 6);
    ctx.fill();

    ctx.fillStyle = "#ffd84d";
    ctx.beginPath();
    ctx.moveTo(18, 0);
    ctx.lineTo(4, -8);
    ctx.lineTo(4, 8);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = "rgba(255,255,255,.75)";
    ctx.fillRect(-5, -7, 9, 14);
    ctx.restore();
  }

  function drawMessage() {
    if (!message || msgTimer <= 0) return;

    ctx.save();
    ctx.globalAlpha = Math.min(1, msgTimer / 30);
    ctx.fillStyle = "rgba(0,0,0,.62)";
    ctx.beginPath();
    ctx.roundRect(W / 2 - 210, H * .22 - 42, 420, 84, 20);
    ctx.fill();

    ctx.fillStyle = "#fff";
    ctx.font = `900 ${Math.max(22, 30 * scale)}px system-ui`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(message, W / 2, H * .22 - 10);

    if (subMessage) {
      ctx.fillStyle = "rgba(255,255,255,.74)";
      ctx.font = `800 ${Math.max(13, 15 * scale)}px system-ui`;
      ctx.fillText(subMessage, W / 2, H * .22 + 22);
    }

    ctx.restore();
  }

  function finishRun() {
    running = false;
    done = true;

    const oldBest = best;
    const medal = medalFor(elapsed);
    const resultLine = `${medal.icon} ${medal.name}`;

    if (!best || elapsed < best) {
      best = elapsed;
      localStorage.setItem(bestKey, String(best));
      message = oldBest ? "NEW BEST" : "FIRST TIME SET";
      subMessage = oldBest ? `${fmt(oldBest - best)}s faster` : resultLine;
    } else {
      message = resultLine;
      subMessage = `${fmt(elapsed - best)}s off your best`;
    }

    msgTimer = 190;

    setTimeout(() => {
      overlay.style.display = "grid";
      overlay.querySelector("h1").textContent = `${medal.icon} ${fmt(elapsed)}s`;
      overlay.querySelectorAll("p")[0].innerHTML = `Two laps complete. Best <b>${fmt(best)}</b>. ${nextMedalText(elapsed)}`;
      overlay.querySelectorAll("p")[1].innerHTML = `Light off-road slowdown is active, so the clean line wins.`;
      overlay.querySelectorAll("p")[2].innerHTML = `Press <b>R</b> or tap below to retry.`;
      startBtn.textContent = "Retry two-lap run";
    }, 900);
  }

  function completeLap() {
    const lapTime = elapsed - lapStartTime;
    const delta = lapTime - lapTarget;
    splitText = (delta <= 0 ? "-" : "+") + fmt(Math.abs(delta));

    if (lap >= totalLaps) {
      finishRun();
      return;
    }

    message = "LAP " + lap + " COMPLETE";
    subMessage = splitText + " vs lap target";
    msgTimer = 78;

    lap++;
    cp = 0;
    lapStartTime = elapsed;
    lastCpTime = elapsed;
  }

  function physics(dt) {
    if (!running || done) return;

    offRoad = !pointOnTrack(car.x, car.y);

    const accel = keys.up ? (offRoad ? 185 : 255) : 0;
    const brake = keys.down ? 355 : 0;
    const maxSpeed = offRoad ? 235 : 365;
    const drag = offRoad ? .955 : .985;

    car.v += accel * dt;
    car.v -= brake * dt * Math.sign(car.v || 1);
    car.v *= Math.pow(drag, dt * 60);
    car.v = Math.max(-115, Math.min(maxSpeed, car.v));

    const steer = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
    const grip = Math.min(1, Math.abs(car.v) / 180);
    car.a += steer * grip * 3.25 * dt * (car.v >= 0 ? 1 : -1);

    car.x += Math.cos(car.a) * car.v * dt;
    car.y += Math.sin(car.a) * car.v * dt;

    car.trail.push({ x: car.x, y: car.y });
    if (car.trail.length > 90) car.trail.shift();

    elapsed = (performance.now() - t0) / 1000;

    if (cp < checkpoints.length) {
      const c = checkpoints[cp];
      const d = Math.hypot(car.x - c.x, car.y - c.y);

      if (d < c.r) {
        const segment = elapsed - lastCpTime;
        const targetSegment = cp === 0 ? checkpoints[0].target : checkpoints[cp].target - checkpoints[cp - 1].target;
        const delta = segment - targetSegment;
        splitText = (delta <= 0 ? "-" : "+") + fmt(Math.abs(delta));

        cp++;
        lastCpTime = elapsed;

        message = delta <= 0 ? "GOOD SPLIT" : "SLOW SPLIT";
        subMessage = splitText + " vs sector target";
        msgTimer = 54;
      }
    } else {
      const gateDist = distToSegment(car.x, car.y, startGate.a.x, startGate.a.y, startGate.b.x, startGate.b.y);
      const nearGate = gateDist < 34;

      if (nearGate && !car.wasNearGate) {
        completeLap();
      }

      car.wasNearGate = nearGate;
    }

    if (cp < checkpoints.length) {
      car.wasNearGate = false;
    }

    msgTimer--;
    updateHud();
  }

  let last = performance.now();

  function loop(now) {
    const dt = Math.min(.033, (now - last) / 1000);
    last = now;

    physics(dt);

    ctx.clearRect(0, 0, W, H);
    drawTrack();
    drawCheckpoints();
    drawNextArrow();
    drawCar();
    drawMessage();

    requestAnimationFrame(loop);
  }

  reset(false);
  requestAnimationFrame(loop);
})();
</script>
